#include<bits/stdc++.h>
#include<atcoder/all>

using namespace std;
using namespace atcoder;

int main(){
  int n,m,e;
  cin >> n >> m >> e;
  vector<int> u(e),v(e);
  for(int i=0;i<e;i++){
    cin >> u[i] >> v[i];
    u[i]--;v[i]--;
  }

  vector<int> fl(e,1);
  int q;
  cin >> q;
  vector<int> query(q);
  for(auto &nx : query){
    cin >> nx;
    nx--;
    fl[nx]=0;
  }

  dsu uf(n+m);
  vector<int> w(n+m,0);
  for(int i=n;i<n+m;i++){w[i]=1;}
  int cur=0;
  for(int i=0;i<e;i++){
    if(fl[i]==0){continue;}
    if(uf.same(u[i],v[i])){continue;}
    int fu=w[uf.leader(u[i])];
    int fv=w[uf.leader(v[i])];
    if(fu==0 && fv==1){cur+=uf.size(u[i]);}
    if(fu==1 && fv==0){cur+=uf.size(v[i]);}
    uf.merge(u[i],v[i]);
    w[uf.leader(u[i])]=max(fu,fv);
  }

  vector<int> res;
  for(int j=q-1;j>=0;j--){
    int i=query[j];
    res.push_back(cur);
    if(uf.same(u[i],v[i])){continue;}
    int fu=w[uf.leader(u[i])];
    int fv=w[uf.leader(v[i])];
    if(fu==0 && fv==1){cur+=uf.size(u[i]);}
    if(fu==1 && fv==0){cur+=uf.size(v[i]);}
    uf.merge(u[i],v[i]);
    w[uf.leader(u[i])]=max(fu,fv);
  }

  reverse(res.begin(),res.end());
  for(auto &nx : res){cout << nx << "\n";}
  return 0;
}

#include <bits/stdc++.h>
#include <atcoder/dsu>

using namespace std;

int main() {
    int n, m, e;
    cin >> n >> m >> e;

    vector<pair<int, int>> uv;
    for(int i = 0; i < e; i++) {
        int u, v;
        cin >> u >> v;
        --u, --v;
        //発電所を全て地点 N と同一視しています
        uv.emplace_back(min(u, n), min(v, n));
    }

    int q;
    cin >> q;
    vector query(q, 0);
    for(auto &v : query) cin >> v, --v;

    vector def_edges(e, true);
    for(auto v : query) def_edges[v] = false;

    atcoder::dsu uf(n + 1);
    for(int i = 0; i < e; i++) {
        if(def_edges[i]) {
            auto [u, v] = uv[i];
            uf.merge(u, v);
        }
    }

    vector<int> ans(q);
    for(int i = q - 1; i >= 0; i--) {
        ans[i] = uf.size(n) - 1;
        auto [u, v] = uv[query[i]];
        uf.merge(u, v);
    }

    for(auto v : ans) cout << v << endl;
}
